const x = $input.first().json;
const fallbackImage = 'https://raw.githubusercontent.com/tha0rbej/hanoixanh/main/anh-chien-dich-kenh-muong.png';
const toIso = (value, field) => {
  const v = String(value ?? '').trim();
  if (!v) return null;
  const withT = v.replace(/^(\d{4}-\d{2}-\d{2})\s+/, '$1T');
  const hasZone = /(Z|[+-]\d{2}:?\d{2})$/i.test(withT);
  const full = hasZone ? withT : (/^\d{4}-\d{2}-\d{2}$/.test(withT) ? withT + 'T00:00:00' : withT) + '+07:00';
  const t = Date.parse(full);
  if (Number.isNaN(t)) throw new Error('invalid_datetime: ' + field + '=' + v);
  return new Date(t).toISOString();
};
const parseJson = (value, field, fallback) => {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { throw new Error('invalid_json: ' + field); }
};
const safeImage = value => { const v = String(value ?? '').trim(); return /^https:\/\/\S+$/i.test(v) ? v : null; };
if (!String(x.finding_id || '').trim()) throw new Error('missing_information: finding_id');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(x.finding_id).trim())) throw new Error('finding_not_found: finding_id không phải uuid hợp lệ');
const start = toIso(x.cleanup_start_at, 'cleanup_start_at');
if (!start) throw new Error('missing_information: cleanup_start_at');
const end = toIso(x.cleanup_end_at, 'cleanup_end_at');
if (!end) throw new Error('missing_information: cleanup_end_at');
if (Date.parse(end) <= Date.parse(start)) throw new Error('invalid_datetime: cleanup_end_at phải sau cleanup_start_at');
const website = parseJson(x.website_payload, 'website_payload', null);
const threads = parseJson(x.threads_payload, 'threads_payload', null);
if (!website || typeof website !== 'object' || !String(website.title || '').trim()) throw new Error('invalid_payload: website_payload cần có title');
if (!threads || typeof threads !== 'object' || !String(threads.text || threads.content || '').trim()) throw new Error('invalid_payload: threads_payload cần có text');
if (String(threads.text || threads.content).length > 500) throw new Error('threads_text_too_long: tối đa 500 ký tự');
const images = parseJson(x.images, 'images', []);
const sources = parseJson(x.sources, 'sources', []);
if (!Array.isArray(images) || !Array.isArray(sources)) throw new Error('invalid_json: images và sources phải là array');
const validImages = images.filter(image => safeImage(typeof image === 'string' ? image : image?.url));
const imageUrl = validImages.map(image => safeImage(typeof image === 'string' ? image : image?.url)).find(Boolean) || fallbackImage;
const storedImages = validImages.length ? validImages : [{ url: fallbackImage, caption: 'Ảnh chiến dịch Hà Nội Xanh', source_url: fallbackImage, license_status: 'project_asset' }];
website.image_url = safeImage(website.image_url) || imageUrl;
threads.image_url = safeImage(threads.image_url) || imageUrl;
return [{ json: { ...x, cleanup_start_at: start, cleanup_end_at: end, meeting_point: x.meeting_point || null, contact: x.contact || null, website_payload: website, threads_payload: threads, images: storedImages, sources } }];

const x = $('Validate Draft Input').first().json;
const finding = $input.first().json;
if (!finding.id) throw new Error('finding_not_found: finding_id không tồn tại hoặc không thuộc thread hiện tại. Hãy tìm lại bằng search_pollution_locations hoặc hỏi admin chọn địa điểm khác.');
const location = [finding.location_name, finding.address, finding.district].filter(Boolean).join(', ') || x.website_payload.location || 'Hà Nội';
const compact = value => String(value || '').replace(/\s+/g, ' ').trim();
const sentences = value => compact(value).split(/(?<=[.!?。！？])\s+/).map(item => item.trim()).filter(item => item.length >= 12);
const sourceSummary = sentences(finding.summary).find(item => /ô nhiễm\s+(nặng|nghiêm trọng)|rác thải|nước thải|bèo tây|tắc dòng chảy|rác tồn đọng/i.test(item)) || sentences(finding.summary)[0] || '';
const requestedPollution = compact(x.website_payload.pollution_status);
const pollutionStatus = compact((sentences(requestedPollution).find(item => /ô nhiễm\s+(nặng|nghiêm trọng)|rác thải|nước thải|bèo tây|tắc dòng chảy|rác tồn đọng/i.test(item)) || sourceSummary).slice(0, 180)) || `Ghi nhận điểm ô nhiễm cần xử lý tại ${location}.`;
const objective = String(x.website_payload.objective || '').trim() || `Thu gom và xử lý điểm ô nhiễm tại ${location}, khơi thông khu vực và ngăn rác tái tồn đọng.`;
const supportEquipment = String(x.website_payload.support_equipment || '').trim() || 'Bao tay, kẹp gắp rác, bao tải, dụng cụ thu gom và nước sát khuẩn do Hà Nội Xanh chuẩn bị.';
const website = { ...x.website_payload, pollution_status: pollutionStatus, objective, support_equipment: supportEquipment, schedule: { ...(x.website_payload.schedule || {}), start_at: x.cleanup_start_at, end_at: x.cleanup_end_at, timezone: 'Asia/Ho_Chi_Minh', location } };
return [{ json: { ...x, website_payload: website } }];
